Your expense tracker is below: add an item, pick a category, and set a monthly budget to see what's left. It lives only in this page, so the entries clear when you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
h2{margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:100px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:#e53e3e;padding:4px 8px}
.big{font-size:22px;font-weight:600}
.bar{height:8px;background:#2b6cb0;border-radius:4px}
.track{background:#e2e8f0;border-radius:4px;margin:2px 0 8px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.over{color:#e53e3e}.ok{color:#2f855a}
small{color:#666}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
  <div class="row">
    <input id="name" placeholder="What did you spend on?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Other</option>
    </select>
    <button onclick="add()">Add</button>
  </div>
</div>
<div class="card">
  <div class="row">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)" oninput="draw()">
  </div>
  <div>Spent: <span class="big" id="total">₹0</span></div>
  <div id="left"></div>
</div>
<div class="card"><b>By category</b><div id="cats"><small>Nothing yet.</small></div></div>
<div class="card"><b>Entries</b><div id="list"><small>Nothing yet.</small></div></div>
<script>
var items=[];
function fmt(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function add(){
  var n=document.getElementById("name").value.trim();
  var a=parseFloat(document.getElementById("amt").value);
  if(!n||!(a>0))return;
  items.push({n:n,a:a,c:document.getElementById("cat").value});
  document.getElementById("name").value="";
  document.getElementById("amt").value="";
  draw();
}
function del(i){items.splice(i,1);draw()}
function draw(){
  var t=0,by={};
  items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a});
  document.getElementById("total").textContent=fmt(t);
  var b=parseFloat(document.getElementById("budget").value);
  var l=document.getElementById("left");
  if(b>0){
    var d=b-t;
    l.innerHTML=d>=0?'<span class="ok">'+fmt(d)+' left of your budget</span>':'<span class="over">'+fmt(-d)+' over your budget</span>';
  }else l.innerHTML="";
  var c=document.getElementById("cats");
  var keys=Object.keys(by);
  c.innerHTML=keys.length?keys.map(function(k){
    var p=t?by[k]/t*100:0;
    return '<div>'+k+' <small>'+fmt(by[k])+' ('+Math.round(p)+'%)</small></div><div class="track"><div class="bar" style="width:'+p+'%"></div></div>';
  }).join(""):"<small>Nothing yet.</small>";
  var li=document.getElementById("list");
  li.innerHTML=items.length?items.map(function(x,i){
    return '<div class="item"><span>'+esc(x.n)+' <small>'+x.c+'</small></span><span>'+fmt(x.a)+' <button class="x" onclick="del('+i+')">✕</button></span></div>';
  }).join(""):"<small>Nothing yet.</small>";
}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
</script>
</body></html>
```

Here is your water tracker with a goal of 8 glasses. Tap a glass to add it, and it saves for today so a new day starts at zero.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; background: #f0f8ff; color: #0b3c5d; }
  h1 { margin: 0 0 4px; font-size: 22px; }
  #count { font-size: 48px; font-weight: 700; margin: 12px 0 4px; }
  #msg { margin-bottom: 16px; min-height: 22px; }
  #bar { height: 14px; background: #d6e9f5; border-radius: 7px; overflow: hidden; max-width: 320px; margin: 0 auto 20px; }
  #fill { height: 100%; width: 0; background: #2e9be6; transition: width .3s; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 360px; margin: 0 auto 20px; }
  .g { width: 56px; height: 72px; border: 2px solid #2e9be6; border-radius: 4px 4px 12px 12px; background: #fff; cursor: pointer; font-size: 26px; line-height: 72px; }
  .g.full { background: #2e9be6; color: #fff; }
  button { font-size: 16px; padding: 8px 16px; margin: 0 4px; border: 0; border-radius: 8px; background: #0b3c5d; color: #fff; cursor: pointer; }
  button.alt { background: #8aa8bd; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button onclick="change(-1)">− Remove</button>
  <button onclick="change(1)">+ Add glass</button>
  <button class="alt" onclick="reset()">Reset</button>
<script>
  var GOAL = 8;
  var key = "water-" + new Date().toISOString().slice(0, 10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key)) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, n); } catch (e) {} }
  function change(d) { n = Math.max(0, n + d); save(); render(); }
  function reset() { n = 0; save(); render(); }
  function setTo(i) { n = (n === i + 1) ? i : i + 1; save(); render(); }

  function render() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      d.textContent = i < n ? "💧" : "";
      d.onclick = (function (k) { return function () { setTo(k); }; })(i);
      box.appendChild(d);
    }
  }
  render();
</script>
</body>
</html>
```
